  const sil=(s,c,w)=>s.replace(/fill="(?!none)[^"]*"/g,`fill="${c}"`).replace(/stroke="[^"]*"/g,`stroke="${c}"`).replace(/stroke-width="([\d.]+)"/g,(a,v)=>`stroke-width="${(+v+w).toFixed(1)}"`).replace(/ opacity="[^"]*"/g,'');
